	/** 
	 * jumpstart the process by instantiating2 Operation
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		operationId = OperationService.getOperationInstance()
		.createOperation( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		OperationService.getOperationInstance()
				.createOperation( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.operationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Operation : " + successValue.getOperationId());
							  if (successValue.getOperationId().equals(operationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfOperationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Operation test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on operation consumed")
					);
			subscriber.operationSubscribe( operationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Operation : " + successValue.getOperationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfOperationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on operation for operationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Operation. 
	 */
	protected Operation read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Operation" );

		Operation entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Operation with primary key" );
		msg.append( operationId );
		
		OperationFetchOneSummary fetchOneSummary = new OperationFetchOneSummary( operationId );

		try {
			entity = OperationService.getOperationInstance().getOperation( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Operation " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Operation.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Operation." );

		StringBuilder msg = new StringBuilder( "Failed to update a Operation : " );        
		Operation entity = read();
		UpdateOperationCommand command = generateUpdateCommand();
		command.setOperationId(entity.getOperationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Operation." );

			// for use later on...
			operationId = entity.getOperationId();

			OperationService proxy = OperationService.getOperationInstance();  

			proxy.updateOperation( command ).get();

			LOGGER.info( "-- Successfully saved Operation - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + operationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Operation.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Operation." );

		Operation entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Operation with id " + operationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Operation with id " + operationId );

			throw e;
		}

		try{
			OperationService.getOperationInstance().delete( new DeleteOperationCommand( entity.getOperationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Operation with id " + operationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Operation with id " + operationId );

			throw e;
		}
	}

	/**
	 * get all Operations.
	 */
	protected List<Operation> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Operations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Operation : " );        
		List<Operation> collection  = new ArrayList<>();

		try {
			// call the static get method on the OperationService
			collection = OperationService.getOperationInstance().getAllOperation();
			assertNotNull( collection, "An Empty collection of Operation was incorrectly returned.");
			
			// Now print out the values
			Operation entity = null;            
			Iterator<Operation> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getOperationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

